
export interface PropertyImage {
    id: string;
    url: string;
    alt: string;
    /** Provider-side handle, e.g. "media:69376". Not used for rendering. */
    storageKey: string;
    provider: string;
    order: number;
    isCover: boolean;
    format: string;
    // The provider does not populate intrinsic dimensions or file size, so
    // `next/image` has to be given explicit sizes wherever these are rendered.
    width?: number | null;
    height?: number | null;
    bytes?: number | null;
}

/**
 * Mirrors the payload served by the Immotech backend.
 *
 * The API always emits every key and uses `null` for "not applicable" — it does
 * not omit fields. Nullable entries are typed `?: T | null` so consumers stay
 * correct whether a value arrives as `null` today or is dropped from the payload
 * later; test with `!= null` rather than a truthiness check, since `0` is a
 * meaningful value for floors, bathrooms and areas.
 */
export interface Property {
    // ── Identity ──────────────────────────────────────────────────────────
    id: string;
    slug: string;
    title: string;
    description: string;
    propertyRef: string;
    agencyId: string;

    // ── Lifecycle ─────────────────────────────────────────────────────────
    createdAt: string;
    updatedAt: string;
    /** Null while a listing is still a draft. */
    publishedAt?: string | null;

    // ── Classification ────────────────────────────────────────────────────
    category: string;
    transactionType: string;
    propertyCondition: string;
    propertyStatus: string;
    listingStatus: string;
    standingLeveling: string;
    isFeatured: boolean;
    isExclusive: boolean;

    // ── Pricing ───────────────────────────────────────────────────────────
    price: number;
    currency: string;
    isPriceOnRequest: boolean;
    deposit?: number | null;
    commissionRate?: number | null;

    // ── Location ──────────────────────────────────────────────────────────
    city: string;
    neighborhood?: string | null;
    address?: string | null;
    latitude?: number | null;
    longitude?: number | null;

    // ── Dimensions & layout ───────────────────────────────────────────────
    totalArea: number;
    livingArea: number;
    landArea?: number | null;
    bedrooms: number;
    /** Frequently null in the current dataset — always guard before rendering. */
    bathrooms?: number | null;
    parkingSpaces: number;
    floorNumber?: number | null;
    totalFloors?: number | null;
    isFurnished: boolean;

    // ── Building & legal ──────────────────────────────────────────────────
    buildingAge?: number | null;
    yearBuilt?: number | null;
    orientation?: string | null;
    syndicateFees?: number | null;
    legalStatus?: string | null;
    titleDeedRef?: string | null;
    availableFrom?: string | null;

    // ── Assignment ────────────────────────────────────────────────────────
    assignedToId?: string | null;

    // ── Amenities ─────────────────────────────────────────────────────────
    hasBasement: boolean;
    hasSecurity: boolean;
    hasBalcony: boolean;
    hasTerrace: boolean;
    hasElevator: boolean;
    hasAirConditioning: boolean;
    hasPool: boolean;
    hasEquippedKitchen: boolean;
    hasEasyAccess: boolean;
    hasGarden: boolean;
    hasOceanView: boolean;
    hasHeating: boolean;
    hasConcierge: boolean;

    // ── Media ─────────────────────────────────────────────────────────────
    coverImage: PropertyImage;
    images: PropertyImage[];
    /** Flat mirror of `images[].url`. Kept because the payload carries it. */
    imageUrls: string[];
}


