    isPriceOnRequest: false,
    deposit: null,
    description: "Appartement 2 chambres à louer – Centre-ville Mimosas, Kénitra\n\nÀ louer, appartement fonctionnel et bien situé au cœur du centre-ville, dans le quartier Mimosas, à proximité du secteur Poids Lourds, dans une rue très calme.\n\nSitué au 5ᵉ étage d’un immeuble propre et bien entretenu.\n\nComposition :\n	•	2 chambres\n	•	Salon lumineux\n	•	Cuisine\n	•	2 salles de bain\n	•	Pré-installation de climatisation (appareils non fournis)\n\nEmplacement stratégique :\nL’appartement bénéficie d’une proximité immédiate avec toutes les commodités : gare de Kénitra à quelques minutes, écoles, lycées et crèches, commerces de proximité et supermarchés, mosquées, transports et services du centre-ville.\n\nCe logement convient parfaitement à un couple, une petite famille ou des personnes travaillant en centre-ville souhaitant un environnement calme tout en restant proche de tout.\n\nLoyer : 3 700 DH par mois\nFrais de syndic inclus\n\nPour plus d’informations ou pour organiser une visite, merci de nous contacter.",
