    isPriceOnRequest: false,
    deposit: null,
    description: "Rez-de-Jardin Haut Standing - Vue Partielle sur Mer \n\nVenez découvrir ce superbe rez-de-jardin de 210 m², entièrement rénové, situé dans une résidence haut de gamme. Idéal pour une famille ou un investissement, ce bien exceptionnel allie confort, élégance et prestations de qualité.\n\n Points forts :\n✔ 3 chambres avec parquet, dont une suite parentale avec dressing, salle de bain privative et accès à la terrasse avec vue partielle sur mer.\n✔ 2 salons modernes, dont un avec cheminée pour une ambiance chaleureuse.\n✔ Séjour spacieux et lumineux.\n✔ Cuisine équipée haut de gamme avec accès à une cour.\n✔ Chambre de service pour plus de praticité.\n✔ 2 salles de bain & 3 toilettes, finitions impeccables.\n✔ Magnifique terrasse idéale pour se détendre.\n\n Un bien d’exception offrant des espaces généreux, une luminosité incroyable et des matériaux de qualité pour un cadre de vie raffiné.\nNe ratez pas cette opportunité unique ! Contactez-nous dès maintenant pour plus de détails ou organiser une visite.",
