    title: "شقة جديدة زوينة للكراء فـ الطابق الثاني فـ بير رامي جنوب، القنيطرة",
    slug: "apartment-rent-bir-rami-ref18a",
    category: "Apartment",
    transactionType: "Rent",
    price: 3000,
    currency: "MAD",
    isPriceOnRequest: false,
    deposit: null,
    description: ": شقة جديدة مازال ما تسكناتش، غير مفروشة، فـ الطابق الثاني ديال دار جديدة  فـ بير رامي جنوبية. الشقة مفينيا مزيان، والشمس كي دخل ليها مزيان، كتوفّر ليك راحة وعصري العيش.\n\nكتكون من جوج ديال البيوت كبار،  زوج صالونات واسعين ومشرقين، حمّام، ومطبخ مجهّز مزيان. كاين حتى بالكون باش تقدر تستمتع بوقتك. الشقة قريبة من الطرانسبور العمومي، قاعات الرياضة، الحمّام، المدارس ديال الصغار، والمسجد، يعني كلشي قريب ليك باش تعيش مرتاح.\n\nما تفلتش الفرصة تكون أول واحد يسكن فـ هاد الشقة الجديدة. تاصل بينا دابا باش نديرو ليك موعد للزيارة!",
